staff_router = APIRouter(
    prefix="/staff",
    dependencies=[Depends(require_support_agent)]
)

@staff_router.patch("/support/tickets/{ticket_id}/assign")
def assign_support_ticket(
    ticket_id: int,
    body: TicketAssignment,
    agent: SupportStaff = Depends(get_current_support_agent),
    db: Session = Depends(get_db)
):
    ticket = db.query(SupportTicket).filter(SupportTicket.id == ticket_id).first()
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")

    if ticket.region_code != agent.region_code:
        raise HTTPException(status_code=403, detail="Ticket outside agent's assigned regional jurisdiction")

    ticket.assigned_agent_id = body.target_agent_id
    db.commit()
    return {"status": "reassigned", "ticket_id": ticket_id}
